// Copyright (c) 2026 Joshua Kato. See LICENSE and NOTICE.
//
// Run investigation (G0 M10 D20; F239, F241, F232, F284, F234, F248). Every
// read runs in the org's tenant transaction and returns agent ids, so the
// caller filters by the viewer's scope before assembling or counting
// (HR-247, D8). Nothing here asserts causation.
// One transaction with its run, grant, permit and execution (F239).
func (q *Queries) InvTransaction(ctx context.Context, orgID ids.OrgID, iD ids.UUID) (InvTransactionRow, error) {
	row := q.db.QueryRow(ctx, invTransaction, orgID, iD)
	var i InvTransactionRow
	err := row.Scan(
		&i.ID,
		&i.RunID,
		&i.AgentID,
		&i.Operation,
		&i.Decision,
		&i.ReasonCode,
		&i.State,
		&i.Mode,
		&i.Channel,
		&i.ConnectionID,
		&i.TargetType,
		&i.TargetID,
		&i.GrantID,
		&i.GrantRevision,
		&i.EffectState,
		&i.EffectLevelRequired,
		&i.EffectLevelAchieved,
		&i.Simulated,
		&i.CreatedAt,
		&i.PermitState,
		&i.DispatchingAt,
		&i.FinishedAt,
		&i.Outcome,
		&i.OutcomeAt,
		&i.DestinationClass,
	)
	return i, err
}
